//go:build reference

package reference_test

import (
	"database/sql"
	"math/big"
	"strconv"
	"strings"
	"testing"
)

// Exact mathematical decimal inputs, not values generated by either SQL backend.
func referenceIntervalBinaryDecimal(numerator int64, shift uint) string {
	denominator := new(big.Int).Lsh(big.NewInt(1), shift)
	decimal := new(big.Rat).SetFrac(big.NewInt(numerator), denominator).FloatString(int(shift))
	digits := strings.TrimPrefix(decimal, "0.")
	first := 0
	for digits[first] == '0' {
		first++
	}
	significand := strings.TrimRight(digits[first:], "0")
	mantissa := significand[:1]
	if len(significand) > 1 {
		mantissa += "." + significand[1:]
	}
	return mantissa + "e-" + strconv.Itoa(first+1)
}

func TestReferenceIntervalISOUnderflow(t *testing.T) {
	cases := []struct {
		name, number string
		reject       bool
	}{
		{"zero_result", "1e-400", true},
		{"inexact_subnormal", "5e-324", true},
		{"exact_tiny", referenceIntervalBinaryDecimal(1, 1074), false},
		{"exact_normal", referenceIntervalBinaryDecimal(1, 1022), false},
		{"exact_largest_subnormal", referenceIntervalBinaryDecimal((1<<52)-1, 1074), false},
		{"normal_minus_half_tiny", referenceIntervalBinaryDecimal((1<<53)-1, 1075), true},
		{"normal_minus_quarter_tiny", referenceIntervalBinaryDecimal((1<<54)-1, 1076), false},
		{"normal_minus_threequarter_tiny", referenceIntervalBinaryDecimal((1<<54)-3, 1076), false},
		{"true_zero", "0e-400", false},
		{"small_normal", "1e-300", false},
	}
	for _, tc := range cases {
		tc.name = "negative/" + tc.name
		tc.number = "-" + tc.number
		cases = append(cases, tc)
	}
	for _, tc := range cases {
		for _, place := range []struct{ name, prefix, suffix, out string }{
			{"time_first", "PT", "S", "00:00:00"}, {"time_later", "P1DT", "S", "1 day"},
			{"date_first", "P", "Y", "00:00:00"}, {"date_later", "P1Y", "M", "1 year"},
			{"date_alternative_first", "P", "", "00:00:00"}, {"time_alternative_first", "PT", "", "00:00:00"},
			{"date_alternative_month", "P1-", "-1", "1 year 1 day"}, {"date_alternative_day", "P1-1-", "", "1 year 1 mon"},
			{"time_alternative_minute", "PT1:", ":1", "01:00:01"}, {"time_alternative_second", "PT1:1:", "", "01:01:00"},
		} {
			t.Run(tc.name+"/"+place.name, func(t *testing.T) {
				p := newReferencePair(t)
				input := place.prefix + tc.number + place.suffix
				out := place.out
				for _, backend := range []struct {
					name   string
					db     *sql.DB
					record *referenceRecorder
				}{{"native", p.memory, p.memoryRecord}, {"postgres", p.postgres, p.postgresRecord}} {
					t.Run(backend.name, func(t *testing.T) {
						run := func(s referenceStep) { referenceRunStep(t, p.ctx, backend.db, backend.record, s) }
						run(referenceExec("CREATE TABLE iv(v INTERVAL)", 0))
						run(referenceExec("INSERT INTO iv VALUES('1 second')", 1))
						sentinel := func() {
							run(referenceSelect("SELECT v FROM iv WHERE v=INTERVAL '1 second'", []string{"v"}, []string{"INTERVAL"}, [][]any{{"00:00:01"}}))
						}
						if tc.reject {
							base := referenceDiagnostic{Code: "22007", Message: "invalid input syntax for type interval: \"" + input + "\""}
							for _, prepared := range []bool{false, true} {
								for _, literal := range []struct{ q, pos string }{{"SELECT INTERVAL '" + input + "' FROM iv", "17"}, {"INSERT INTO iv VALUES('" + input + "')", "23"}, {"INSERT INTO iv VALUES('1 day'),('" + input + "')", "33"}} {
									want := base
									want.Position = literal.pos
									s := referenceImplicitError(literal.q, want)
									s.prepared = prepared
									s.errorStage = "execute"
									if prepared {
										s.errorStage = "prepare"
									}
									run(s)
									run(referenceSelect("SELECT v FROM iv", []string{"v"}, []string{"INTERVAL"}, [][]any{{"00:00:01"}}))
								}
								for _, parameter := range []struct {
									q, context string
									args       []any
								}{
									{"INSERT INTO iv VALUES($1)", "unnamed portal parameter $1 = '...'", []any{input}},
									{"INSERT INTO iv VALUES($1),($2)", "unnamed portal parameter $2 = '...'", []any{"1 day", input}},
								} {
									s := referenceImplicitError(parameter.q, base, parameter.args...)
									s.prepared = prepared
									s.errorStage = "execute"
									pg := *s.diagnostic
									pg.Context = parameter.context
									s.postgresDiagnostic = &pg
									run(s)
									run(referenceSelect("SELECT v FROM iv", []string{"v"}, []string{"INTERVAL"}, [][]any{{"00:00:01"}}))
								}
							}
							return
						}
						var previous int64
						for _, prepared := range []bool{false, true} {
							for _, parameterized := range []bool{false, true} {
								run(referenceExec("DELETE FROM iv WHERE v<>INTERVAL '1 second'", previous))
								s := referenceExec("INSERT INTO iv VALUES('"+input+"')", 1)
								if parameterized {
									s = referenceExec("INSERT INTO iv VALUES($1)", 1, input)
								}
								s.prepared = prepared
								run(s)
								previous = 1
								run(referenceSelect("SELECT v FROM iv WHERE v<>INTERVAL '1 second'", []string{"v"}, []string{"INTERVAL"}, [][]any{{out}}))
								sentinel()
							}
						}
					})
				}
			})
		}
	}
}

func TestReferenceIntervalISOUnderflowSessionIsolation(t *testing.T) {
	p := newReferencePair(t)
	for _, backend := range []struct {
		db     *sql.DB
		record *referenceRecorder
	}{{p.memory, p.memoryRecord}, {p.postgres, p.postgresRecord}} {
		referenceRunStep(t, p.ctx, backend.db, backend.record, referenceExec("CREATE TABLE iv(v INTERVAL)", 0))
		referenceRunStep(t, p.ctx, backend.db, backend.record, referenceExec("INSERT INTO iv VALUES('1 second')", 1))
		a, err := backend.db.Conn(p.ctx)
		if err != nil {
			t.Fatal(err)
		}
		defer a.Close()
		b, err := backend.db.Conn(p.ctx)
		if err != nil {
			t.Fatal(err)
		}
		defer b.Close()
		referenceRunStep(t, p.ctx, a, backend.record, referenceExec("SET IntervalStyle=sql_standard", 0))
		referenceRunStep(t, p.ctx, b, backend.record, referenceExec("SET IntervalStyle=iso_8601", 0))
		for _, prepared := range []bool{false, true} {
			s := referenceImplicitError("INSERT INTO iv VALUES($1),($2)", referenceDiagnostic{Code: "22007", Message: "invalid input syntax for type interval: \"P1DT1e-400S\""}, "1 day", "P1DT1e-400S")
			s.prepared = prepared
			s.errorStage = "execute"
			pg := *s.diagnostic
			pg.Context = "unnamed portal parameter $2 = '...'"
			s.postgresDiagnostic = &pg
			referenceRunStep(t, p.ctx, a, backend.record, s)
			referenceRunStep(t, p.ctx, a, backend.record, referenceSelect("SHOW IntervalStyle", []string{"IntervalStyle"}, []string{"TEXT"}, [][]any{{"sql_standard"}}))
			referenceRunStep(t, p.ctx, b, backend.record, referenceSelect("SHOW IntervalStyle", []string{"IntervalStyle"}, []string{"TEXT"}, [][]any{{"iso_8601"}}))
			referenceRunStep(t, p.ctx, a, backend.record, referenceSelect("SELECT v FROM iv", []string{"v"}, []string{"INTERVAL"}, [][]any{{"0:00:01"}}))
			referenceRunStep(t, p.ctx, b, backend.record, referenceSelect("SELECT v FROM iv", []string{"v"}, []string{"INTERVAL"}, [][]any{{"PT1S"}}))
		}
	}
}
